igcaption><strong><?= e($caption) ?></strong><small><?= $orthoDate($captureDate) ?><?= !empty($file['phase'])?' · '.e($file['phase']):'' ?></small><small><?= e($file['author'] ?? $file['professional'] ?? '') ?></small><?php if(!empty($file['description'])): ?><p><?= e($file['description']) ?></p><?php endif; ?><a href="<?= e(url('/admin/attachment?id='.$attachmentId)) ?>" class="orth-link">Descargar original</a></figcaption></figure><?php endforeach; ?></div><p class="orth-empty" data-orth-photos-empty hidden>No hay imágenes que coincidan con estos filtros.</p>
